import java.io.*;import java.util.*;public class Main {static class FastScanner {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st;String next() {while (st == null || !st.hasMoreTokens()) {try {String l = br.readLine();if (l == null) return null;st = new StringTokenizer(l);} catch (IOException e) {return null;}}return st.nextToken();}int nextInt() {return Integer.parseInt(next());}}public static void main(String[] args) {FastScanner sc = new FastScanner();String nStr = sc.next();if (nStr == null) return;int n = Integer.parseInt(nStr);long[] count = new long[100001];for (int i = 0; i < n; i++) {int val = sc.nextInt();count[val]++;}long[] dp = new long[100001];dp[0] = 0;dp[1] = count[1];for (int i = 2; i <= 100000; i++) {dp[i] = Math.max(dp[i - 1], dp[i - 2] + (long) i * count[i]);}System.out.println(dp[100000]);}}